/**
 * Cross-cutting registration contract of the RDF4J SPARQL extension functions: the SPI service files, the registries
 * that load them and the {@code model-vocabulary} constants must agree with each other.
 * <p>
 * {@link GEOX} functions live in the {@code rdf4j-queryalgebra-geosparql} module, which is not on this module's
 * classpath; their registry lookup is asserted by {@code GeoExtensionFunctionsTest} in that module. This class only
 * checks that no {@code geox:} function leaks into the core service files.
 */
public class ExtensionFunctionRegistrationContractTest {

	private static final String SERVICES = "META-INF/services/";
	private static final String FUNCTION_SERVICE = SERVICES + Function.class.getName();
	private static final String TUPLE_FUNCTION_SERVICE = SERVICES + TupleFunction.class.getName();
	private static final String AGGREGATE_SERVICE = SERVICES + AggregateFunctionFactory.class.getName();
	private static final String AGGREGATE_NARY_SERVICE = SERVICES + AggregateNAryFunctionFactory.class.getName();

	private static final String FUNCTION_NAMESPACE_ROOT = "http://rdf4j.org/function/";

	/** Scalar/tuple vocabularies keyed by namespace; GEOX is listed so its namespace is recognised as an extension. */
	private static final Map<String, Class<?>> VOCABULARIES_BY_NAMESPACE = vocabularies();

	/** Constants that are implemented as set-returning functions ({@link TupleFunction}) rather than scalars. */
	private static final Set<IRI> TUPLE_FUNCTION_CONSTANTS = Set.of(STRF.split, STRF.regexpExtractAll,
			TEXTF.tokenize, TEXTF.ngrams, ARRAYF.unnest, ARRAYF.unnestWithOrdinality, ARRAYF.generateSeries);

	private static Map<String, Class<?>> vocabularies() {
		Map<String, Class<?>> map = new LinkedHashMap<>();
		map.put(MATHF.NAMESPACE, MATHF.class);
		map.put(STRF.NAMESPACE, STRF.class);
		map.put(DTF.NAMESPACE, DTF.class);
		map.put(WINF.NAMESPACE, WINF.class);
		map.put(TEXTF.NAMESPACE, TEXTF.class);
		map.put(JSONF.NAMESPACE, JSONF.class);
		map.put(ARRAYF.NAMESPACE, ARRAYF.class);
		map.put(GEOX.NAMESPACE, GEOX.class);
		map.put(BITF.NAMESPACE, BITF.class);
		map.put(ENCF.NAMESPACE, ENCF.class);
		map.put(MISCF.NAMESPACE, MISCF.class);
		return map;
	}

	@Test
	public void functionServiceFileClassesExistAreInstantiableAndUnique() throws Exception {
		List<String> entries = serviceEntries(FUNCTION_SERVICE);
		assertThat(entries).as("scan sanity").hasSizeGreaterThan(150);
		assertUniqueAndInstantiable(entries, Function.class);
		assertThat(entries).as("geox functions belong to the geosparql module's service file")
				.noneMatch(name -> name.contains(".geosparql."));
		for (String name : entries) {
			Function function = (Function) instantiate(name);
			assertThat(function.getURI()).as(name + " reports an IRI").isNotBlank();
			assertThat(FunctionRegistry.getInstance().get(function.getURI()))
					.as(name + " is registered under " + function.getURI())
					.isPresent();
		}
	}

	@Test
	public void tupleFunctionServiceFileClassesExistAreInstantiableAndUnique() throws Exception {
		List<String> entries = serviceEntries(TUPLE_FUNCTION_SERVICE);
		assertThat(entries).as("scan sanity").hasSizeGreaterThanOrEqualTo(7);
		assertUniqueAndInstantiable(entries, TupleFunction.class);
		for (String name : entries) {
			TupleFunction function = (TupleFunction) instantiate(name);
			assertThat(TupleFunctionRegistry.getInstance().get(function.getURI()))
					.as(name + " is registered under " + function.getURI())
					.isPresent();
		}
	}

	@Test
	public void aggregateServiceFilesAreInstantiableUniqueAndDisjoint() throws Exception {
		List<String> unary = serviceEntries(AGGREGATE_SERVICE);
		List<String> nary = serviceEntries(AGGREGATE_NARY_SERVICE);
		assertThat(unary).as("scan sanity").isNotEmpty();
		assertThat(nary).as("scan sanity").isNotEmpty();
		assertUniqueAndInstantiable(unary, AggregateFunctionFactory.class);
		assertUniqueAndInstantiable(nary, AggregateNAryFunctionFactory.class);
		Set<String> overlap = new TreeSet<>(unary);
		overlap.retainAll(nary);
		assertThat(overlap).as("a factory must be either unary or N-ary, never both").isEmpty();

		Set<String> unaryIris = new TreeSet<>();
		for (String name : unary) {
			String iri = ((AggregateFunctionFactory) instantiate(name)).getIri();
			assertThat(CustomAggregateFunctionRegistry.getInstance().get(iri)).as(name).isPresent();
			assertThat(unaryIris.add(iri)).as("duplicate aggregate IRI " + iri).isTrue();
		}
		Set<String> naryIris = new TreeSet<>();
		for (String name : nary) {
			String iri = ((AggregateNAryFunctionFactory) instantiate(name)).getIri();
			assertThat(CustomAggregateNAryFunctionRegistry.getInstance().get(iri)).as(name).isPresent();
			assertThat(naryIris.add(iri)).as("duplicate N-ary aggregate IRI " + iri).isTrue();
		}
		unaryIris.retainAll(naryIris);
		assertThat(unaryIris).as("an aggregate IRI must resolve in exactly one aggregate registry").isEmpty();
	}

	@Test
	public void everyScalarVocabularyConstantResolvesThroughFunctionRegistry() {
		List<String> missing = new ArrayList<>();
		for (Class<?> vocabulary : List.of(MATHF.class, STRF.class, DTF.class, TEXTF.class, JSONF.class,
				ARRAYF.class, BITF.class, ENCF.class, MISCF.class)) {
			for (IRI constant : constants(vocabulary)) {
				boolean scalar = FunctionRegistry.getInstance().has(constant.stringValue());
				boolean tuple = TupleFunctionRegistry.getInstance().has(constant.stringValue());
				if (!scalar && !tuple) {
					missing.add(constant.stringValue());
				}
				if (TUPLE_FUNCTION_CONSTANTS.contains(constant)) {
					assertThat(tuple).as(constant + " is a set-returning function").isTrue();
				} else {
					assertThat(scalar).as(constant + " is a scalar function").isTrue();
				}
			}
		}
		assertThat(missing).as("vocabulary constants without any registered implementation").isEmpty();
	}

	@Test
	public void everyTupleFunctionConstantResolvesThroughTupleFunctionRegistry() {
		for (IRI constant : TUPLE_FUNCTION_CONSTANTS) {
			assertThat(TupleFunctionRegistry.getInstance().get(constant.stringValue())).as(constant.stringValue())
					.isPresent();
		}
		// the scalar twins of the set-returning string/text functions are registered as well
		for (IRI constant : List.of(STRF.split, STRF.regexpExtractAll, TEXTF.tokenize, TEXTF.ngrams,
				ARRAYF.generateSeries)) {
			assertThat(FunctionRegistry.getInstance().get(constant.stringValue())).as(constant.stringValue())
					.isPresent();
		}
	}

	@Test
	public void everyWindowVocabularyConstantResolvesThroughFunctionRegistry() {
		Set<IRI> constants = constants(WINF.class);
		assertThat(constants).hasSize(22);
		for (IRI constant : constants) {
			assertThat(FunctionRegistry.getInstance().get(constant.stringValue()))
					.as(constant + " (window function or window specification marker)")
					.isPresent();
		}
	}

	@Test
	public void everyAggregateVocabularyConstantResolvesInAnAggregateRegistry() {
		Set<IRI> constants = constants(AGGF.class);
		assertThat(constants).hasSize(22);
		for (IRI constant : constants) {
			boolean unary = CustomAggregateFunctionRegistry.getInstance().has(constant.stringValue());
			boolean nary = CustomAggregateNAryFunctionRegistry.getInstance().has(constant.stringValue());
			assertThat(unary || nary).as(constant + " resolves in an aggregate registry").isTrue();
			assertThat(unary && nary).as(constant + " resolves in exactly one aggregate registry").isFalse();
		}
	}

	@Test
	public void everyRegisteredExtensionFunctionUriIsAVocabularyConstant() {
		List<String> unknown = new ArrayList<>();
		for (Function function : FunctionRegistry.getInstance().getAll()) {
			checkExtensionIri(function.getURI(), function.getClass().getName(), unknown);
		}
		for (TupleFunction function : TupleFunctionRegistry.getInstance().getAll()) {
			checkExtensionIri(function.getURI(), function.getClass().getName(), unknown);
		}
		Set<IRI> aggregates = constants(AGGF.class);
		Set<String> aggregateIris = new TreeSet<>();
		aggregates.forEach(iri -> aggregateIris.add(iri.stringValue()));
		for (AggregateFunctionFactory factory : CustomAggregateFunctionRegistry.getInstance().getAll()) {
			if (factory.getIri().startsWith(AGGF.NAMESPACE) && !aggregateIris.contains(factory.getIri())) {
				unknown.add(factory.getClass().getName() + " -> " + factory.getIri());
			}
		}
		for (AggregateNAryFunctionFactory factory : CustomAggregateNAryFunctionRegistry.getInstance().getAll()) {
			if (factory.getIri().startsWith(AGGF.NAMESPACE) && !aggregateIris.contains(factory.getIri())) {
				unknown.add(factory.getClass().getName() + " -> " + factory.getIri());
			}
		}
		assertThat(unknown).as("extension functions whose getURI() has no model-vocabulary constant").isEmpty();
	}

	private static void checkExtensionIri(String iri, String implementation, List<String> unknown) {
		if (!iri.startsWith(FUNCTION_NAMESPACE_ROOT)) {
			return;
		}
		String namespace = iri.substring(0, iri.indexOf('#') + 1);
		Class<?> vocabulary = VOCABULARIES_BY_NAMESPACE.get(namespace);
		if (vocabulary == null) {
			unknown.add(implementation + " -> " + iri + " (no vocabulary class for namespace " + namespace + ")");
			return;
		}
		boolean found = false;
		for (IRI constant : constants(vocabulary)) {
			if (constant.stringValue().equals(iri)) {
				found = true;
				break;
			}
		}
		if (!found) {
			unknown.add(implementation + " -> " + iri + " (missing in " + vocabulary.getSimpleName() + ")");
		}
	}

	private static Set<IRI> constants(Class<?> vocabulary) {
		Set<IRI> constants = new LinkedHashSet<>();
		for (Field field : vocabulary.getFields()) {
			if (field.getType() == IRI.class && Modifier.isStatic(field.getModifiers())) {
				try {
					constants.add((IRI) field.get(null));
				} catch (IllegalAccessException e) {
					throw new AssertionError(e);
				}
			}
		}
		return constants;
	}

	private static void assertUniqueAndInstantiable(List<String> entries, Class<?> contract) throws Exception {
		Set<String> seen = new LinkedHashSet<>();
		List<String> duplicates = new ArrayList<>();
		for (String entry : entries) {
			if (!seen.add(entry)) {
				duplicates.add(entry);
			}
		}
		assertThat(duplicates).as("duplicate entries in " + SERVICES + contract.getName()).isEmpty();
		for (String entry : entries) {
			Object instance = instantiate(entry);
			assertThat(instance).as(entry + " implements " + contract.getSimpleName()).isInstanceOf(contract);
		}
	}

	private static Object instantiate(String className) throws Exception {
		Class<?> type = Class.forName(className, true, Function.class.getClassLoader());
		return type.getDeclaredConstructor().newInstance();
	}

	private static List<String> serviceEntries(String resource) throws Exception {
		List<String> entries = new ArrayList<>();
		Enumeration<URL> resources = Function.class.getClassLoader().getResources(resource);
		while (resources.hasMoreElements()) {
			URL url = resources.nextElement();
			try (BufferedReader reader = new BufferedReader(
					new InputStreamReader(url.openStream(), StandardCharsets.UTF_8))) {
				String line;
				while ((line = reader.readLine()) != null) {
					String name = line.trim();
					int comment = name.indexOf('#');
					if (comment >= 0) {
						name = name.substring(0, comment).trim();
					}
					if (!name.isEmpty()) {
						entries.add(name);
					}
				}
			}
		}
		return entries;
	}
}
